import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readdirSync } from "node:fs";
import { AT, compare, fixtures, observe, observeResolved } from "./helpers/comparison.js";

// diff over the comparison material: a reference certificate and variants that each change one
// thing about it, generated by scripts/generate-certs.sh. The material is generated again with new
// keys and dates, so nothing here writes down a serial, a date or a fingerprint: it compares fields
// of the observations of one run, and writes down only what the generator writes as text (the
// names, the usages and the common name).

/** What two different certificates always differ in, in the order of `changes`. */
const ALWAYS = ["serial", "notBefore", "notAfter", "sha256"];
/** The fields of the key. `spkiSha256` is the one that says the key itself is another. */
const KEY = ["key.algorithm", "key.size", "key.curve", "spkiSha256"];

/**
 * @param {string} name A fixture.
 * @returns {any} Its target certificate.
 */
function targetOf(name) {
    const observation = observe(name);
    return observation.certificates[observation.target];
}

/**
 * The delta of two fixtures, for two different certificates: they differ in the serial, the dates
 * and the fingerprint, each as one `changed` with the values the two observations hold.
 * @param {string} before
 * @param {string} after
 * @returns {any}
 */
function different(before, after) {
    const delta = compare(observe(before), observe(after));
    const was = targetOf(before);
    const is = targetOf(after);
    assert.equal(delta.identical, false);
    for (const field of ALWAYS) {
        const changes = delta.changes.filter((/** @type {any} */ change) => change.field === field);
        assert.deepEqual(changes, [{ field, direction: "changed", before: was[field], after: is[field] }], field);
        assert.notEqual(was[field], is[field], `${field} is another in the two certificates`);
    }
    return delta;
}

/**
 * What a delta holds besides the four fields that two different certificates always change.
 * @param {any} delta
 * @returns {any[]}
 */
function besides(delta) {
    return delta.changes.filter((/** @type {any} */ change) => !ALWAYS.includes(change.field));
}

/**
 * @param {any} delta
 * @returns {string[]}
 */
function fieldsOf(delta) {
    return delta.changes.map((/** @type {any} */ change) => change.field);
}

// ---------------------------------------------------------------------------------------------
// The material

const SAME_KEY = ["pagos-reissue", "pagos-san-more", "pagos-san-less", "pagos-san-swapped", "pagos-no-eku", "pagos-client-auth", "pagos-other-subject", "pagos-expired", "pagos-second-issuer"];
const OTHER_KEY = ["pagos-other-key", "pagos-p384", "pagos-rsa4096"];

test("the comparison material is what its names say: the reference, the variants that keep its key and the three that change it, signed in a later second", () => {
    const reference = targetOf("pagos.pem");
    assert.equal(reference.subject.cn, "pagos.example.com");
    assert.deepEqual(reference.san.dns, ["api.pagos.example.com", "pagos.example.com"]);
    assert.deepEqual(reference.eku, ["serverAuth"]);
    assert.deepEqual(reference.key, { algorithm: "ec", size: 256, curve: "P-256" });
    assert.equal(reference.kind, "end-entity");

    // The intermediate that signs it is the one the bundle sends with it, and the other bundle sends the second.
    const withIntermediate = observe("bundle-pagos.pem");
    assert.equal(withIntermediate.certificates.length, 2);
    assert.equal(withIntermediate.certificates[withIntermediate.target].sha256, reference.sha256);
    const [signer] = withIntermediate.certificates.filter((_, index) => index !== withIntermediate.target);
    assert.equal(signer.kind, "ca");
    assert.deepEqual(withIntermediate.certificates[withIntermediate.target].issuer, signer.subject);
    const withSecond = observe("bundle-pagos-second-issuer.pem");
    const [second] = withSecond.certificates.filter((_, index) => index !== withSecond.target);
    assert.deepEqual(withSecond.certificates[withSecond.target].issuer, second.subject);
    assert.notDeepEqual(second.subject, signer.subject);
    assert.notEqual(second.sha256, signer.sha256);

    for (const name of SAME_KEY) {
        const variant = targetOf(`${name}.pem`);
        assert.equal(variant.spkiSha256, reference.spkiSha256, `${name} keeps the key`);
        assert.equal(variant.kind, "end-entity", name);
    }
    for (const name of OTHER_KEY) {
        assert.notEqual(targetOf(`${name}.pem`).spkiSha256, reference.spkiSha256, `${name} has another key`);
    }
    // One second between the reference and every variant: the dates of two certificates signed in
    // the same second would be equal, and a variant would look like the reference in them.
    for (const name of [...SAME_KEY, ...OTHER_KEY].filter((name) => name !== "pagos-expired")) {
        const variant = targetOf(`${name}.pem`);
        assert.ok(Date.parse(variant.notBefore) > Date.parse(reference.notBefore), `${name} is signed after the reference`);
        assert.ok(Date.parse(variant.notAfter) > Date.parse(reference.notAfter), `${name} ends after the reference`);
    }
    assert.ok(Date.parse(targetOf("pagos-expired.pem").notAfter) < AT.getTime(), "the expired variant has ended");

    for (const name of ["pagos", ...SAME_KEY, ...OTHER_KEY]) {
        for (const suffix of ["pem", "key", "mismatch.key", "ext"]) {
            assert.ok(existsSync(new URL(`${name}.${suffix}`, fixtures)), `${name}.${suffix}`);
        }
    }
});

// ---------------------------------------------------------------------------------------------
// The pairs

test("the reference with itself is identical and has no change", () => {
    const delta = compare(observe("pagos.pem"), observe("pagos.pem"));
    assert.equal(delta.identical, true);
    assert.deepEqual(delta.changes, []);
});

test("the reference and its reissue under the same key change only the serial, the dates and the fingerprint, and not spkiSha256", () => {
    const delta = different("pagos.pem", "pagos-reissue.pem");
    assert.deepEqual(fieldsOf(delta), ALWAYS);
    assert.deepEqual(besides(delta), []);
});

test("the reference and one under another P-256 key change spkiSha256 and not key.algorithm, key.size or key.curve", () => {
    const delta = different("pagos.pem", "pagos-other-key.pem");
    assert.deepEqual(fieldsOf(delta), [...ALWAYS, "spkiSha256"]);
    assert.deepEqual(besides(delta), [{ field: "spkiSha256", direction: "changed", before: targetOf("pagos.pem").spkiSha256, after: targetOf("pagos-other-key.pem").spkiSha256 }]);
});

test("the reference and one with a SAN name more have san.dns added, with only that name", () => {
    const delta = different("pagos.pem", "pagos-san-more.pem");
    assert.deepEqual(besides(delta), [{ field: "san.dns", direction: "added", after: "status.pagos.example.com" }]);
    assert.deepEqual(delta.changes.filter((/** @type {any} */ change) => KEY.includes(change.field)), []);
});

test("the reference and one with a SAN name less have san.dns removed, with only that name", () => {
    const delta = different("pagos.pem", "pagos-san-less.pem");
    assert.deepEqual(besides(delta), [{ field: "san.dns", direction: "removed", before: "api.pagos.example.com" }]);
    assert.deepEqual(delta.changes.filter((/** @type {any} */ change) => KEY.includes(change.field)), []);
});

test("the reference and one that adds clientAuth have eku added, clientAuth, and the same pair reversed has it removed", () => {
    assert.deepEqual(besides(different("pagos.pem", "pagos-client-auth.pem")), [{ field: "eku", direction: "added", after: "clientAuth" }]);
    assert.deepEqual(besides(different("pagos-client-auth.pem", "pagos.pem")), [{ field: "eku", direction: "removed", before: "clientAuth" }]);
});

test("the reference and one with no Extended Key Usage extension have eku changed from [serverAuth] to null", () => {
    const delta = different("pagos.pem", "pagos-no-eku.pem");
    assert.deepEqual(besides(delta), [{ field: "eku", direction: "changed", before: ["serverAuth"], after: null }]);
    assert.deepEqual(besides(different("pagos-no-eku.pem", "pagos.pem")), [{ field: "eku", direction: "changed", before: null, after: ["serverAuth"] }]);
});

test("the P-384 key and the reference have key.size and key.curve changed, and key.algorithm not", () => {
    const delta = different("pagos-p384.pem", "pagos.pem");
    assert.deepEqual(besides(delta), [
        { field: "key.size", direction: "changed", before: 384, after: 256 },
        { field: "key.curve", direction: "changed", before: "P-384", after: "P-256" },
        { field: "spkiSha256", direction: "changed", before: targetOf("pagos-p384.pem").spkiSha256, after: targetOf("pagos.pem").spkiSha256 },
    ]);
    assert.equal(fieldsOf(delta).includes("key.algorithm"), false);
});

test("the reference with its intermediate and one signed by the other intermediate with that one have a chain removed and added at one position, and the issuer fields changed", () => {
    const before = observe("bundle-pagos.pem");
    const after = observe("bundle-pagos-second-issuer.pem");
    const delta = compare(before, after);
    const link = (/** @type {any} */ observation) => observation.certificates.filter((/** @type {any} */ _, /** @type {number} */ index) => index !== observation.target)[0];
    const was = targetOf("bundle-pagos.pem");
    const is = targetOf("bundle-pagos-second-issuer.pem");

    assert.equal(delta.identical, false);
    assert.deepEqual(besides(delta), [
        { field: "issuer.cn", direction: "changed", before: was.issuer.cn, after: is.issuer.cn },
        { field: "issuer.dn", direction: "changed", before: was.issuer.dn, after: is.issuer.dn },
        { field: "chain", direction: "removed", before: { position: 0, sha256: link(before).sha256 } },
        { field: "chain", direction: "added", after: { position: 0, sha256: link(after).sha256 } },
    ]);
    assert.notEqual(was.issuer.dn, is.issuer.dn);
    // Their keys and names are the reference's.
    assert.deepEqual(delta.changes.filter((/** @type {any} */ change) => KEY.includes(change.field) || change.field.startsWith("san.")), []);
});

test("the reference with its intermediate and the reference alone are identical and have one chain removed", () => {
    const before = observe("bundle-pagos.pem");
    const delta = compare(before, observe("pagos.pem"));
    const [link] = before.certificates.filter((_, index) => index !== before.target);
    assert.equal(delta.identical, true);
    assert.deepEqual(delta.changes, [{ field: "chain", direction: "removed", before: { position: 0, sha256: link.sha256 } }]);
    // And the other way round, the intermediate is added.
    const reversed = compare(observe("pagos.pem"), before);
    assert.equal(reversed.identical, true);
    assert.deepEqual(reversed.changes, [{ field: "chain", direction: "added", after: { position: 0, sha256: link.sha256 } }]);
});

test("a bundle whose chain is in another order has the same target and one chain changed, with the links of each side in its own order", () => {
    // The same three certificates: bundle-ordered sends leaf, intermediate, root and bundle-shuffled
    // sends root, leaf, intermediate, so the target is at 0 in one and at 1 in the other and the
    // positions of the links are still counted among the others.
    const before = observe("bundle-ordered.pem");
    const after = observe("bundle-shuffled.pem");
    assert.notEqual(before.target, after.target);
    const links = (/** @type {any} */ observation) => observation.certificates.filter((/** @type {any} */ _, /** @type {number} */ index) => index !== observation.target).map((/** @type {any} */ certificate) => certificate.sha256);
    const delta = compare(before, after);
    assert.equal(delta.identical, true);
    assert.deepEqual(delta.changes, [{ field: "chain", direction: "changed", before: links(before), after: links(after) }]);
    assert.deepEqual(links(before).slice().reverse(), links(after));
});

test("the reference and one with another subject have subject.cn and subject.dn changed", () => {
    const delta = different("pagos.pem", "pagos-other-subject.pem");
    assert.deepEqual(besides(delta), [
        { field: "subject.cn", direction: "changed", before: "pagos.example.com", after: "cobros.example.com" },
        { field: "subject.dn", direction: "changed", before: "CN=pagos.example.com", after: "CN=cobros.example.com" },
    ]);
});

test("the reference and one with an RSA 4096 key have key.algorithm, key.size, key.curve and spkiSha256 changed", () => {
    const delta = different("pagos.pem", "pagos-rsa4096.pem");
    assert.deepEqual(besides(delta), [
        { field: "key.algorithm", direction: "changed", before: "ec", after: "rsa" },
        { field: "key.size", direction: "changed", before: 256, after: 4096 },
        { field: "key.curve", direction: "changed", before: "P-256", after: null },
        { field: "spkiSha256", direction: "changed", before: targetOf("pagos.pem").spkiSha256, after: targetOf("pagos-rsa4096.pem").spkiSha256 },
    ]);
});

test("the reference and one with a SAN name more and another less have two independent changes, one removed and one added", () => {
    const delta = different("pagos.pem", "pagos-san-swapped.pem");
    assert.deepEqual(besides(delta), [
        { field: "san.dns", direction: "removed", before: "api.pagos.example.com" },
        { field: "san.dns", direction: "added", after: "v2.pagos.example.com" },
    ]);
});

test("the pair with a SAN name less, reversed, has san.dns added and the dates changed in the other sense", () => {
    const forward = different("pagos.pem", "pagos-san-less.pem");
    const reversed = different("pagos-san-less.pem", "pagos.pem");
    assert.deepEqual(besides(reversed), [{ field: "san.dns", direction: "added", after: "api.pagos.example.com" }]);
    for (const field of ["notBefore", "notAfter"]) {
        const [was] = forward.changes.filter((/** @type {any} */ change) => change.field === field);
        const [is] = reversed.changes.filter((/** @type {any} */ change) => change.field === field);
        assert.ok(Date.parse(was.after) > Date.parse(was.before), `${field} moves forward from the reference to the variant`);
        assert.ok(Date.parse(is.after) < Date.parse(is.before), `${field} moves backward when the arguments are reversed`);
        assert.deepEqual([is.before, is.after], [was.after, was.before]);
    }
});

test("the reference and the same one already expired have only the serial, the dates and the fingerprint changed", () => {
    const delta = different("pagos.pem", "pagos-expired.pem");
    assert.deepEqual(fieldsOf(delta), ALWAYS);
    assert.deepEqual(besides(delta), []);
    assert.ok(Date.parse(targetOf("pagos-expired.pem").notAfter) < Date.parse(targetOf("pagos.pem").notBefore));
});

// ---------------------------------------------------------------------------------------------
// Every fixture

test("a difference between two certificates is never an error: every fixture observation, compared with the reference and with itself, gives a Delta that validates", () => {
    const names = readdirSync(fixtures).filter((name) => /\.(pem|der)$/.test(name)).sort();
    assert.ok(names.length > 40, `found ${names.length} certificate fixtures`);
    const reference = observe("pagos.pem");

    /** @type {Set<string>} */
    const seen = new Set();
    for (const name of names) {
        const observation = observeResolved(name);
        const toIt = compare(reference, observation);
        const fromIt = compare(observation, reference);
        const itself = compare(observation, observation);
        assert.equal(itself.identical, true, name);
        assert.deepEqual(itself.changes, [], name);
        assert.equal(toIt.identical, fromIt.identical, name);
        assert.equal(toIt.changes.length, fromIt.changes.length, `${name}: swapping the arguments keeps the number of changes`);
        for (const delta of [toIt, fromIt]) {
            for (const change of delta.changes) {
                seen.add(`${change.field} ${change.direction}`);
                if (change.before === null || change.after === null) seen.add(`${change.field} null`);
            }
        }
    }
    // The walk met every kind of value and every shape of chain, so no kind was left out of it.
    for (const wanted of [
        "kind changed", "selfSigned changed", "subject.cn null", "issuer.cn changed", "san.dns added", "san.dns removed", "san.ip added", "san.email added",
        "san.uri added", "eku changed", "eku null", "eku added", "eku removed", "key.algorithm null", "key.size null", "key.curve null",
        "chain added", "chain removed",
    ]) {
        assert.ok(seen.has(wanted), `no comparison produced "${wanted}"; saw ${[...seen].join(", ")}`);
    }
});
